CREATE TABLE "commercial_events" (
	"seq" bigint GENERATED BY DEFAULT AS IDENTITY (sequence name "commercial_events_seq_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"id" text PRIMARY KEY NOT NULL,
	"event" text NOT NULL,
	"organization_id" text,
	"plan_key" text,
	"capability" text,
	"old_value_json" text,
	"new_value_json" text,
	"reason" text NOT NULL,
	"expires_at" timestamp(3) with time zone,
	"actor_user_id" text NOT NULL,
	"request_id" text,
	"created_at" timestamp(3) with time zone NOT NULL,
	CONSTRAINT "commercial_events_event" CHECK ("commercial_events"."event" IN ('plan.assigned', 'plan.entitlement_changed', 'override.set', 'override.removed'))
);
