CREATE TABLE "entitlement_overrides" (
	"seq" bigint GENERATED BY DEFAULT AS IDENTITY (sequence name "entitlement_overrides_seq_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"id" text PRIMARY KEY NOT NULL,
	"organization_id" text NOT NULL,
	"capability" text NOT NULL,
	"enabled" boolean,
	"limit_value" bigint,
	"unlimited" boolean DEFAULT false NOT NULL,
	"reason" text NOT NULL,
	"expires_at" timestamp(3) with time zone,
	"created_by_user_id" text NOT NULL,
	"created_at" timestamp(3) with time zone NOT NULL,
	"revoked_at" timestamp(3) with time zone,
	"revoked_by_user_id" text,
	CONSTRAINT "entitlement_overrides_one_kind" CHECK (("entitlement_overrides"."enabled" IS NOT NULL) <> ("entitlement_overrides"."limit_value" IS NOT NULL OR "entitlement_overrides"."unlimited")),
	CONSTRAINT "entitlement_overrides_limit" CHECK ("entitlement_overrides"."limit_value" IS NULL OR "entitlement_overrides"."limit_value" >= 0),
	CONSTRAINT "entitlement_overrides_reason" CHECK (length(trim("entitlement_overrides"."reason")) > 0)
);
--> statement-breakpoint
CREATE TABLE "plan_entitlements" (
	"plan_key" text NOT NULL,
	"capability" text NOT NULL,
	"enabled" boolean,
	"limit_value" bigint,
	"updated_at" timestamp(3) with time zone NOT NULL,
	CONSTRAINT "plan_entitlements_plan_key_capability_pk" PRIMARY KEY("plan_key","capability"),
	CONSTRAINT "plan_entitlements_one_kind" CHECK ("plan_entitlements"."enabled" IS NULL OR "plan_entitlements"."limit_value" IS NULL),
	CONSTRAINT "plan_entitlements_limit" CHECK ("plan_entitlements"."limit_value" IS NULL OR "plan_entitlements"."limit_value" >= 0)
);
